={{ (() => {
  const toArr = v => {
    if (Array.isArray(v)) return v;
    if (!v) return [];
    try { return JSON.parse('[' + String(v).trim().replace(/^\{/, '').replace(/\}$/, '') + ']'); } catch (e) { return [String(v)]; }
  };
  const t = (text, b) => ({ type: 'text', text: text, ...(b ? { marks: [{ type: 'strong' }] } : {}) });
  const p = (text) => ({ type: 'paragraph', content: [t(text)] });
  const h = (text) => ({ type: 'heading', attrs: { level: 3 }, content: [t(text)] });
  const ul = (items, bold) => ({
    type: 'bulletList',
    content: items.map(i => {
      const k = bold ? String(i).indexOf(' — ') : -1;
      const nodes = k > 0 ? [t(String(i).slice(0, k), true), t(String(i).slice(k))] : [t(String(i))];
      return { type: 'listItem', content: [{ type: 'paragraph', content: nodes }] };
    })
  });
  const desc = String($json.description ?? '').split('\n').map(l => l.trim()).filter(Boolean).map(p);
  const rules = toArr($json.rules);
  const measures = toArr($json.measures);
  const content = [
    ...desc,
    ...(rules.length ? [h('Règles métier'), ul(rules, false)] : []),
    ...(measures.length ? [h('Mesures de succès'), ul(measures, true)] : [])
  ];
  return {
    fields: {
      project: { key: $('Get project infos').item.json.jira_key },
      issuetype: { name: 'Epic' },
      summary: $json.epic_title,
      description: { type: 'doc', version: 1, content: content }
    }
  };
})() }}

={{ (() => {
  const para = t => ({ type: 'paragraph', content: [{ type: 'text', text: String(t) }] });
  const heading = t => ({ type: 'heading', attrs: { level: 3 }, content: [{ type: 'text', text: t }] });
  const list = a => ({ type: 'bulletList', content: a.map(i => ({ type: 'listItem', content: [para(i)] })) });
  const step = s => { let o = s; if (typeof s === 'string') { try { o = JSON.parse(s); } catch (e) { return s; } } return o && o.title ? o.title + (o.description ? ' : ' + o.description : '') : JSON.stringify(o); };
  const rule = r => typeof r === 'string' ? r : JSON.stringify(r);
  const rules = ($json.feature_rules ?? []).map(rule).filter(x => x.trim());
  const steps = ($json.feature_steps ?? []).map(step).filter(x => x.trim());
  const content = String($json.feature_description ?? '').split('\n').filter(l => l.trim()).map(l => para(l));
  if (rules.length) content.push(heading('Règles métier'), list(rules));
  if (steps.length) content.push(heading('Étapes'), list(steps));
  return {
    fields: {
      project: { key: $('Get project infos').first().json.jira_key },
      issuetype: { id: '10156' },
      summary: $json.feature_title,
      parent: { id: $json.epic_jira_ticket_id },
      description: { type: 'doc', version: 1, content: content }
    }
  };
})() }}

={{ (() => {
  const p = (t, b) => ({ type: 'paragraph', content: [{ type: 'text', text: t, ...(b ? { marks: [{ type: 'strong' }] } : {}) }] });
  const isB = l => /^([-*•]\s|Étant donné|Given)/i.test(l);
  const lines = String($json.story_description ?? '').split('\n').flatMap(l => l.split(/,(?=\s*Étant donné)/i)).map(l => l.replace(/\*\*/g, '').trim()).filter(Boolean);
  const content = lines.reduce((a, l) => {
    const last = a[a.length - 1];
    if (isB(l)) {
      const item = { type: 'listItem', content: [p(l.replace(/^[-*•]\s+/, ''))] };
      if (last && last.type === 'bulletList') { last.content.push(item); } else { a.push({ type: 'bulletList', content: [item] }); }
    } else { a.push(p(l, /^(crit[èe]res|acceptance)/i.test(l))); }
    return a;
  }, []);
  return {
    fields: {
      project: { key: $('Get project infos').first().json.jira_key },
      issuetype: { id: '10119' },
      summary: $json.story_title,
      parent: { id: $json.epic_jira_ticket_id },
      description: { type: 'doc', version: 1, content: content }
    },
    update: { issuelinks: [ { add: { type: { name: 'Relates' }, outwardIssue: { id: $json.feature_jira_ticket_id } } } ] }
  };
})() }}
